3	// Minimal nvcc test TU for the R2 tensor-core substrate (wgmma.cuh /
4	// tile_pipeline.cuh). Compiled via torch.utils.cpp_extension.load() by
5	// tests/hw/test_wgmma_substrate.py (NOT via setup.py — this TU is test-only
6	// and is never part of the shipped build glob).
7	//
8	// Exposes torch-callable entry points that run small, seconds-scale CORRECTNESS
9	// gates on a single CTA (one warpgroup = 128 threads, blockDim.x=128). These
10	// are contention-immune correctness checks, NOT timed benchmarks (perf is a
11	// later quiet-GPU phase): tiny grids, < 1 GB allocations.
12	//
13	// Gates exercised here (driven from python):
14	//   (a) single-tile bf16 GEMM (m64×N×16) vs an fp32 reference of the
15	//       bf16-rounded inputs, over multiple N incl. ragged edges;
16	//   (b) multi-tile K-loop accumulation (the k16 chain over K=128);
17	//   (c) pipelined variant (producer/consumer, 2-3 stages) — same numerics;
18	//   (d) determinism: same inputs -> bitwise-identical outputs;
19	//   (e) occupancy / refuse probe for an oversized dynamic-smem request.
20	//
21	// All operands are bf16 in smem (the design's input dtype), fp32 accumulators.
22	// ─────────────────────────────────────────────────────────────────────────
23	#include <torch/extension.h>
24	#include <c10/cuda/CUDAStream.h>
25	#include <c10/cuda/CUDAException.h>
26	#include <cuda_runtime.h>
27	#include <cuda_bf16.h>
28	#include <cuda/std/utility>   // cuda::std::pair (descriptor-pair return)
29	#include <cstdint>
