34	namespace wgs = sg::sm90::wgs;
35	
36	// =========================================================================
37	//  Helpers shared by the kernels.
38	//
39	//  smem operand layout (no-swizzle, the correctness path):
40	//    A tile: M(=64) rows × K(=16) cols of bf16, ROW-MAJOR  → A[m*16 + k]
41	//    B tile: N      rows × K(=16) cols of bf16, ROW-MAJOR  → B[n*16 + k]
42	//  This is the "K-contiguous" layout make_desc_{A,B}_kmajor describes. The
43	//  wgmma computes D[m,n] = sum_k A[m,k] * B[n,k]  (B read as Kx N, i.e. the
44	//  RHS is the transpose of an N×K row-major tile → TransB=1, TransA=0).
45	//  We therefore feed B already laid out as N×K row-major and the math yields
46	//  D = A @ B^T  in (M×K)·(K×N) terms with B stored N×K. The python reference
47	//  computes exactly torch: D = A_bf16.float() @ B_bf16.float().T over that
48	//  same N×K B — see the test. (Equivalently: B_logical[k,n] = B_stored[n,k].)
49	// =========================================================================
50	
51	template <int N>
52	__global__ void __launch_bounds__(128)
53	gemm_single_tile_kernel(
54	    const __nv_bfloat16* __restrict__ gA,   // [64*16] row-major M×K
55	    const __nv_bfloat16* __restrict__ gB,   // [N*16]  row-major N×K
56	    float* __restrict__ gD,                 // [64*N]  row-major M×N out
57	    int k_steps                              // number of 16-wide K tiles
58	) {
59	#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 900)
60	    // smem operand tiles: one A (64×16) + one B (N×16) per K-step, all staged.
61	    // For the single-tile / K-loop gates we stage ALL k_steps contiguously so
62	    // the descriptor generator just advances a pointer (no pipelining).
63	    extern __shared__ __nv_bfloat16 smem[];
64	    __nv_bfloat16* sA = smem;                       // [k_steps][64*16]
65	    __nv_bfloat16* sB = sA + (size_t)k_steps * 64 * 16; // [k_steps][N*16]
66	
67	    const int tid = threadIdx.x;  // 0..127 (one warpgroup)
68	
69	    // Cooperative load of all K-tiles into smem (plain loads; the staging
70	    // dtype is bf16). 64*16=1024 A elems + N*16 B elems per k-step.
71	    for (int k = 0; k < k_steps; ++k) {
72	        const __nv_bfloat16* aSrc = gA + (size_t)k * 64 * 16;
73	        const __nv_bfloat16* bSrc = gB + (size_t)k * N * 16;
74	        __nv_bfloat16* aDst = sA + (size_t)k * 64 * 16;
75	        __nv_bfloat16* bDst = sB + (size_t)k * N * 16;
76	        for (int i = tid; i < 64 * 16; i += 128) aDst[i] = aSrc[i];
77	        for (int i = tid; i < N * 16;  i += 128) bDst[i] = bSrc[i];
78	    }
79	    __syncthreads();
80	
81	    wgs::WgmmaAccum<N> acc;  // fp32 fragment, N/2 regs/thread
82	
83	    // Descriptor generator: k-step k → {descA, descB} for the pre-staged tiles.
84	    // A tile is 64×16 row-major → row stride = 16 bf16 = 32 bytes.
85	    // B tile is N×16  row-major → row stride = 16 bf16 = 32 bytes.
86	    const uint32_t aRowStride = 16 * sizeof(__nv_bfloat16);  // 32
87	    const uint32_t bRowStride = 16 * sizeof(__nv_bfloat16);  // 32
88	    auto gen = [&] (int k) {
89	        const __nv_bfloat16* aTile = sA + (size_t)k * 64 * 16;
90	        const __nv_bfloat16* bTile = sB + (size_t)k * N * 16;
91	        wgs::SmemDesc dA = wgs::make_desc_A_kmajor<wgs::kSwizzleNone>(aTile, aRowStride);
92	        wgs::SmemDesc dB = wgs::make_desc_B_kmajor<wgs::kSwizzleNone>(bTile, bRowStride);
93	        return cuda::std::pair<wgs::SmemDesc, wgs::SmemDesc>(dA, dB);
94	    };
95	
96	    // The full choreography: fence → (k=0 overwrite, k>0 accumulate) →
97	    // commit → wait_group<0>. TransA=0 (A is M×K row-major), TransB=1
98	    // (B stored N×K is read transposed to K×N for the contraction).
99	    wgs::wgmma_mainloop_kchain<N, /*TransA=*/0, /*TransB=*/1>(acc, k_steps, gen);
100	
101	    // Epilogue: store each thread's N/2 fragment regs to the right (row,col)
102	    // of the M×N output using the authoritative fragment decode.
103	    #pragma unroll
104	    for (int i = 0; i < wgs::WgmmaAccum<N>::kRegs; ++i) {
105	        int row, col;
106	        wgs::wgmma_frag_decode(tid, i, N, row, col);
107	        gD[row * N + col] = acc.c[i];
108	    }
109	#else
110	    (void)gA; (void)gB; (void)gD; (void)k_steps;
111	#endif
112	}
113	
114	// Pipelined variant: producer/consumer warpgroup split staging K-tiles through
115	// an mbarrier ring (tile_pipeline.cuh), proving the choreography. Same numerics
116	// as the unpipelined kernel above (gate c). Uses blockDim.x = 256 (WG0
117	// producer + WG1 consumer).
118	template <int N, int PipeDepth>
119	__global__ void __launch_bounds__(256)
120	gemm_pipelined_kernel(
121	    const __nv_bfloat16* __restrict__ gA,
122	    const __nv_bfloat16* __restrict__ gB,
123	    float* __restrict__ gD,
124	    int k_steps
125	) {
126	#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 900)
127	    wgs::tc_pipelined_gemm_m64nNk16<N, PipeDepth>(gA, gB, gD, k_steps);
128	#else
129	    (void)gA; (void)gB; (void)gD; (void)k_steps;
130	#endif
131	}
