133	// =========================================================================
134	//  Host launchers (torch-callable).
135	// =========================================================================
136	
137	static size_t single_tile_smem_bytes(int N, int k_steps) {
138	    return (size_t)k_steps * (64 * 16 + N * 16) * sizeof(__nv_bfloat16);
139	}
140	
141	// Launch the unpipelined single-tile / K-loop GEMM for a compile-time N.
142	template <int N>
143	static torch::Tensor run_single_tile(torch::Tensor A, torch::Tensor B, int k_steps) {
144	    TORCH_CHECK(A.scalar_type() == torch::kBFloat16, "A must be bf16");
145	    TORCH_CHECK(B.scalar_type() == torch::kBFloat16, "B must be bf16");
146	    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "inputs must be CUDA");
147	    TORCH_CHECK(A.is_contiguous() && B.is_contiguous(), "inputs must be contiguous");
148	    TORCH_CHECK(A.numel() == (int64_t)k_steps * 64 * 16, "A numel mismatch");
149	    TORCH_CHECK(B.numel() == (int64_t)k_steps * N * 16,  "B numel mismatch");
150	
151	    auto D = torch::empty({64, N},
152	                          torch::dtype(torch::kFloat32).device(A.device()));
153	    size_t smem = single_tile_smem_bytes(N, k_steps);
154	    auto stream = at::cuda::getCurrentCUDAStream();
155	
156	    // Allow > 48 KB dynamic smem (opt-in attribute) for larger k_steps.
157	    cudaFuncSetAttribute(gemm_single_tile_kernel<N>,
158	                         cudaFuncAttributeMaxDynamicSharedMemorySize,
159	                         (int)smem);
160	    gemm_single_tile_kernel<N><<<1, 128, smem, stream>>>(
161	        reinterpret_cast<const __nv_bfloat16*>(A.data_ptr()),
162	        reinterpret_cast<const __nv_bfloat16*>(B.data_ptr()),
163	        D.data_ptr<float>(), k_steps);
164	    C10_CUDA_CHECK(cudaGetLastError());
165	    return D;
166	}
167	
168	// Pipelined launcher (compile-time N + depth).
169	template <int N, int PipeDepth>
170	static torch::Tensor run_pipelined(torch::Tensor A, torch::Tensor B, int k_steps) {
171	    TORCH_CHECK(A.scalar_type() == torch::kBFloat16 && B.scalar_type() == torch::kBFloat16);
172	    TORCH_CHECK(A.is_cuda() && B.is_cuda() && A.is_contiguous() && B.is_contiguous());
173	    auto D = torch::empty({64, N},
174	                          torch::dtype(torch::kFloat32).device(A.device()));
175	    // Ring of PipeDepth stages, each one A(64×16)+B(N×16) bf16 tile + the
176	    // mbarrier words.
177	    size_t ring = (size_t)PipeDepth * (64 * 16 + N * 16) * sizeof(__nv_bfloat16);
178	    size_t bars = (size_t)PipeDepth * 2 * sizeof(unsigned long long); // full+empty
179	    size_t smem = ring + bars + 256;  // slack for alignment
180	    auto stream = at::cuda::getCurrentCUDAStream();
181	    cudaFuncSetAttribute(gemm_pipelined_kernel<N, PipeDepth>,
182	                         cudaFuncAttributeMaxDynamicSharedMemorySize, (int)smem);
183	    gemm_pipelined_kernel<N, PipeDepth><<<1, 256, smem, stream>>>(
184	        reinterpret_cast<const __nv_bfloat16*>(A.data_ptr()),
185	        reinterpret_cast<const __nv_bfloat16*>(B.data_ptr()),
186	        D.data_ptr<float>(), k_steps);
187	    C10_CUDA_CHECK(cudaGetLastError());
188	    return D;
189	}
190	
191	// Dispatch over the runtime N to the compile-time template (the design's set).
192	static torch::Tensor gemm_tile(torch::Tensor A, torch::Tensor B, int N, int k_steps) {
193	    switch (N) {
194	        case 8:   return run_single_tile<8>(A, B, k_steps);
195	        case 16:  return run_single_tile<16>(A, B, k_steps);
196	        case 32:  return run_single_tile<32>(A, B, k_steps);
197	        case 64:  return run_single_tile<64>(A, B, k_steps);
198	        case 96:  return run_single_tile<96>(A, B, k_steps);
199	        case 128: return run_single_tile<128>(A, B, k_steps);
200	        default: TORCH_CHECK(false, "unsupported N ", N);
201	    }
202	}
203	
204	static torch::Tensor gemm_tile_pipelined(torch::Tensor A, torch::Tensor B,
205	                                         int N, int k_steps, int depth) {
206	    if (depth == 2) {
207	        switch (N) {
208	            case 64:  return run_pipelined<64, 2>(A, B, k_steps);
209	            case 128: return run_pipelined<128, 2>(A, B, k_steps);
210	            default: TORCH_CHECK(false, "pipelined: unsupported N ", N);
211	        }
212	    } else if (depth == 3) {
213	        switch (N) {
214	            case 64:  return run_pipelined<64, 3>(A, B, k_steps);
215	            case 128: return run_pipelined<128, 3>(A, B, k_steps);
216	            default: TORCH_CHECK(false, "pipelined: unsupported N ", N);
217	        }
218	    }
219	    TORCH_CHECK(false, "pipelined: unsupported depth ", depth);
220	}
