222	// =========================================================================
223	//  Occupancy / refuse probe (gate e). The faithful "occupancy >= 1 or refuse"
224	//  contract: query cudaOccupancyMaxActiveBlocksPerMultiprocessor for a given
225	//  dynamic-smem request; if it is 0 the launch would not be resident → REFUSE
226	//  (return 0) WITHOUT launching (no hang). Also exercises the hard failure
227	//  path: a smem request beyond the device max returns
228	//  cudaErrorLaunchOutOfResources promptly (asserted in python).
229	// =========================================================================
230	static int64_t occupancy_for_smem(int64_t requested_smem_bytes) {
231	    int numBlocks = 0;
232	    cudaError_t e = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
233	        &numBlocks, gemm_single_tile_kernel<128>, 128,
234	        (size_t)requested_smem_bytes);
235	    if (e != cudaSuccess) {
236	        // The query itself rejected the config (e.g. > device max): clear the
237	        // sticky error and report 0 occupancy (refuse). No kernel was launched.
238	        cudaGetLastError();
239	        return 0;
240	    }
241	    return (int64_t)numBlocks;
242	}
243	
244	// Actually attempt an oversized launch and return the cuda error code (the
245	// test asserts it is cudaErrorLaunchOutOfResources, i.e. it fails fast, no
246	// hang). We deliberately request more dynamic smem than any H100 SM has.
247	static int64_t probe_oversized_launch(int64_t requested_smem_bytes) {
248	    auto stream = at::cuda::getCurrentCUDAStream();
249	    // Do NOT set the attribute high enough (the request exceeds the cap); the
250	    // launch must be rejected at launch time.
251	    gemm_single_tile_kernel<128><<<1, 128, (size_t)requested_smem_bytes, stream>>>(
252	        nullptr, nullptr, nullptr, 0);
253	    cudaError_t e = cudaGetLastError();
254	    return (int64_t)e;  // python compares against cudaErrorLaunchOutOfResources (7? -> see test)
255	}
256	
257	// Report the H100 SM dynamic-smem cap so the test can size the oversized probe.
258	static int64_t device_max_dynamic_smem() {
259	    int v = 0;
260	    int dev = 0; cudaGetDevice(&dev);
261	    cudaDeviceGetAttribute(&v, cudaDevAttrMaxSharedMemoryPerBlockOptin, dev);
262	    return (int64_t)v;
263	}
