265	PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
266	    m.def("gemm_tile", &gemm_tile,
267	          "single-tile / K-loop ss-wgmma bf16 GEMM (m64xNx16), fp32 accum");
268	    m.def("gemm_tile_pipelined", &gemm_tile_pipelined,
269	          "pipelined (producer/consumer) ss-wgmma GEMM, same numerics");
270	    m.def("occupancy_for_smem", &occupancy_for_smem,
271	          "max active blocks/SM for a dynamic-smem request (0 = refuse)");
272	    m.def("probe_oversized_launch", &probe_oversized_launch,
273	          "attempt an oversized-smem launch; returns cuda error code (no hang)");
274	    m.def("device_max_dynamic_smem", &device_max_dynamic_smem,
275	          "device cudaDevAttrMaxSharedMemoryPerBlockOptin (bytes)");
276	}
