// Host-only CUTLASS probe: what is the canonical K-major bf16 smem layout and
// the resulting GMMA descriptor LBO/SBO for a 64x16 (A) and 128x16 (B) tile?
#include <cute/tensor.hpp>
#include <cute/atom/mma_traits_sm90_gmma.hpp>
#include <cstdio>
using namespace cute;

template <int M, int K>
void probe(const char* name) {
  // The canonical K-major smem layout CUTLASS builds for an MxK operand tile:
  auto atom = GMMA::Layout_K_INTER_Atom<half_t>{};
  auto smem_layout = tile_to_shape(atom, Shape<Int<M>, Int<K>>{});
  printf("==== %s  (M=%d K=%d) canonical K-major INTER smem layout ====\n", name, M, K);
  print("  smem_layout (bf16 elems): "); print(smem_layout); print("\n");
  // The byte offset of element (m,k) for the FIRST FEW (m,k):
  printf("  byte offsets (elem*2):\n");
  for (int m = 0; m < (M<4?M:4); ++m) {
    printf("    m=%d: ", m);
    for (int k = 0; k < (K<6?K:6); ++k) {
      int off = smem_layout(m, k);
      printf("(k=%d:%d) ", k, off*2);
    }
    printf("\n");
  }
}

int main() {
  probe<64,16>("A m64k16");
  probe<128,16>("B n128k16");
  probe<8,16>("B n8k16");
  // Also: what does a PLAIN ROW-MAJOR (K-contiguous) tile look like? (the buggy staging)
  printf("\n==== PLAIN ROW-MAJOR 64x16 (K-contiguous: A[m*16+k]) — the buggy staging ====\n");
  auto rowmaj = make_layout(Shape<_64,_16>{}, Stride<_16,_1>{});
  print("  layout: "); print(rowmaj); print("\n");
  printf("  m=0: "); for(int k=0;k<6;k++) printf("(k=%d:%d) ",k, rowmaj(0,k)*2); printf("\n");
  printf("  m=1: "); for(int k=0;k<6;k++) printf("(k=%d:%d) ",k, rowmaj(1,k)*2); printf("\n");
  return 0;
}

// Print the ACTUAL GmmaDescriptor LBO/SBO for canonical K-major bf16 tiles,
// using a fake 16B-aligned smem base so the encode runs on host.
#include <cute/tensor.hpp>
#include <cute/atom/mma_traits_sm90_gmma.hpp>
#include <cute/arch/mma_sm90_desc.hpp>
#include <cstdio>
using namespace cute;

template <int M, int K>
void desc_for(const char* nm) {
  auto atom = GMMA::Layout_K_INTER_Atom<half_t>{};
  auto smem_layout = tile_to_shape(atom, Shape<Int<M>, Int<K>>{});
  // Decode the canonical mode strides the way make_gmma_desc<Major::K> does.
  // Recast to uint128_t and logical_divide by ((8,1),(2,1)).
  // Easier: replicate the math. In uint128 units the layout is:
  //   recast<uint128>(smem_layout) then divide.
  // We just print the smem_layout and compute LBO/SBO manually via the doc:
  //   Major-K INTERLEAVE: ((8,n),2):((1,SBO),LBO)  in uint128 units.
  // For our tile: T=8 (bf16 per 128b).
  printf("==== %s M=%d K=%d ====\n", nm, M, K);
  print("  smem(bf16): "); print(smem_layout); print("\n");
  auto u128 = recast<uint128_t const>(smem_layout);
  print("  smem(u128): "); print(u128); print("\n");
  // canonical divide
  Layout canonical = logical_divide(u128, make_tile(Layout<_8,_1>{}, Layout<_2,_1>{}));
  print("  canonical : "); print(canonical); print("\n");
  uint32_t sbo = stride<0,1>(canonical);   // stride_byte_offset_  (u128 units)
  uint32_t lbo = stride<1,0>(canonical);   // leading_byte_offset_ (u128 units)
  printf("  -> SBO (u128 units) = %u  => bytes = %u\n", sbo, sbo*16);
  printf("  -> LBO (u128 units) = %u  => bytes = %u\n", lbo, lbo*16);
  printf("  (descriptor stores these >>4, i.e. the u128-unit value directly)\n");
}

int main() {
  desc_for<64,16>("A m64k16");
  desc_for<128,16>("B n128k16");
  desc_for<8,16>("B n8k16");
  desc_for<64,16>("(again, M-tile=64 means TILE_M=64 atom)");
  return 0;
}

#include <cute/tensor.hpp>
#include <cute/atom/mma_traits_sm90_gmma.hpp>
#include <cute/arch/mma_sm90_desc.hpp>
#include <cstdio>
using namespace cute;

// Build the canonical K-major smem layout, wrap a smem-tagged tensor, call
// make_gmma_desc<Major::K>, and print the resulting descriptor fields.
template <int M, int K>
void desc_for(const char* nm) {
  printf("==== %s M=%d K=%d ====\n", nm, M, K);
  auto atom = GMMA::Layout_K_INTER_Atom<half_t>{};
  auto smem_layout = tile_to_shape(atom, Shape<Int<M>, Int<K>>{});
  print("  smem(bf16): "); print(smem_layout); print("\n");
  // Fake 16B-aligned smem address (the encode only uses (addr>>4) low bits; the
  // LBO/SBO are layout-derived and address-independent).
  alignas(16) static half_t fake[ M*K*4 ];
  auto t = make_tensor(make_smem_ptr(&fake[0]), smem_layout);
  auto desc = GMMA::make_gmma_desc<GMMA::Major::K>(t);
  printf("  LBO (u128 units, =bytes>>4) = %u  => bytes = %u\n",
         (unsigned)desc.bitfield.leading_byte_offset_,
         (unsigned)desc.bitfield.leading_byte_offset_ * 16u);
  printf("  SBO (u128 units, =bytes>>4) = %u  => bytes = %u\n",
         (unsigned)desc.bitfield.stride_byte_offset_,
         (unsigned)desc.bitfield.stride_byte_offset_ * 16u);
  printf("  layout_type = %u (0=INTERLEAVE/none)\n", (unsigned)desc.bitfield.layout_type_);
}

int main() {
  desc_for<64,16>("A m64k16 (TILE_M=64)");
  desc_for<128,16>("B n128k16");
  desc_for<8,16>("B n8k16");
  desc_for<64,16>("B n64k16");
  return 0;
}

