// -------------------------------------------------------------------------
//  Canonical descriptor builders for the bf16 "K-contiguous" smem tiles the
//  model headers stage (DESIGN §4.3: A tile 64×16 bf16, B tile N×16 bf16).
//
//  For swizzle=NONE the operand smem is a plain row-major block. A core
//  matrix is 8 rows × (16 bf16 = 32 bytes) = a 128-bit-wide unit per row.
//  The descriptor's LBO/SBO are the byte distances between core matrices.
//  For the no-swizzle layouts used by the correctness path:
//    * LBO = the byte stride to step ONE core-matrix along the leading dim,
//    * SBO = the byte stride to step ONE core-matrix along the K (stride) dim.
//  The ISA's canonical no-swizzle bf16 operand uses LBO = 16 (×16B = the
//  16-byte row), SBO = 8 rows × leading_stride. We pass the operand's
//  row-stride-in-bytes as `stride_bytes` and derive the canonical offsets.
//  These match the layouts the unpipelined and pipelined gates both load.
// -------------------------------------------------------------------------

// A operand (LHS), shape M×K, K-contiguous in smem (each of M rows is K bf16).
// stride_bytes = byte distance between consecutive M-rows of the A tile.
template <SwizzleMode Swizzle = kSwizzleNone>
__device__ __forceinline__ SmemDesc make_desc_A_kmajor(
    const void* smem_base, uint32_t row_stride_bytes
) {
    // No-swizzle canonical: leading offset = 1 core-matrix row group (16B*... ),
    // stride offset = 8 rows down. Encoded byte offsets; helper applies >>4.
    // (LBO,SBO) for the m64k16 A tile with K-major rows: see §9.7.14.4.3.
    const uint32_t lbo = 16u;                      // 1 core-matrix col step (16B)
    const uint32_t sbo = row_stride_bytes * 8u;    // 8 rows along K stride
    return make_smem_desc<Swizzle>(smem_base, lbo, sbo);
}

// B operand (RHS), shape N×K, K-contiguous in smem (each of N rows is K bf16).
// row_stride_bytes = byte distance between consecutive N-rows of the B tile.
template <SwizzleMode Swizzle = kSwizzleNone>
__device__ __forceinline__ SmemDesc make_desc_B_kmajor(
    const void* smem_base, uint32_t row_stride_bytes
) {
    const uint32_t lbo = 16u;
    const uint32_t sbo = row_stride_bytes * 8u;
    return make_smem_desc<Swizzle>(smem_base, lbo, sbo);
}

