// Init the barriers (one thread of the block). full[] expects ONE producer
// arrival per stage (the producer warp's elected leader issues
// arrive_expect_tx); empty[] expects ONE consumer arrival per stage. We
// PRIME empty[] as already-satisfied for the first Depth fills (the
// producer may fill all Depth stages before any consume) by arriving on
// each empty barrier once at init.
__device__ __forceinline__ void init_barriers() {
    if (threadIdx.x == 0) {
        #pragma unroll
        for (int s = 0; s < Depth; ++s) {
            full(s).init(1);
            empty(s).init(1);
        }
    }
}

